/* res_live.c - the GBA's 500 residents (GBA-500; res_live.h). The sets are generated by
 * tools/gba_live.py into core/gen/live_set.c; the keep rule for old saves is save.c's. */
#include "doomo/res_live.h"

static int bit(const uint8_t *set, int id)
{
    return id >= 0 && id < DOOMO_MAX_RESIDENTS && ((set[id >> 3] >> (id & 7)) & 1);
}

int res_live_must(int id) { return bit(doomo_live_must, id); }
int res_live_default(int id) { return bit(doomo_live_default, id); }
